// build-search.mjs — emit the static full-text search index.
//
// Fumadocs' static client fetches /api/search. This script builds that JSON
// from the synced docs (src/content/docs/_synced/) at build time and writes it
// into the output directory, so search works with zero server endpoints — the
// site stays a fully static Cloudflare Pages deploy.
//
// Run from the `astro:build:done` hook in astro.config.mjs; the input tree is
// the same `_synced/` the content collections read (generated by sync-docs.ts).
import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import { join, relative, resolve } from "node:path";
import { loader } from "fumadocs-core/source";
import { createFromSource } from "fumadocs-core/search/server";
import { structure } from "fumadocs-core/mdx-plugins";

const ROOT = resolve(import.meta.dirname, "..");
const SYNCED = join(ROOT, "src/content/docs/_synced");

async function walk(dir) {
  const out = [];
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const ent of entries) {
    const abs = join(dir, ent.name);
    if (ent.isDirectory()) out.push(...(await walk(abs)));
    else out.push(abs);
  }
  return out;
}

/** Same shape as sync-docs.ts's parser — frontmatter block + body. */
function parseFrontmatter(raw) {
  if (!raw.startsWith("---\n")) return { body: raw, meta: {} };
  const end = raw.indexOf("\n---", 4);
  if (end === -1) return { body: raw, meta: {} };
  const block = raw.slice(4, end);
  const body = raw.slice(end + 4).replace(/^\n/, "");
  const meta = {};
  for (const line of block.split("\n")) {
    const m = line.match(/^([a-zA-Z0-9_-]+):\s*(.*)$/);
    if (m) meta[m[1]] = m[2].replace(/^"(.*)"\s*$/, "$1");
  }
  return { body, meta };
}

export async function buildSearchIndex(distDir) {
  const files = [];
  const mcpPages = [];
  const sections = [];
  let pageCount = 0;

  // Sorted so every index (and the unqueried /search.json) is stable across filesystems.
  for (const abs of (await walk(SYNCED)).sort()) {
    const rel = relative(SYNCED, abs).split(/[\\/]/).join("/");
    if (abs.endsWith(".md")) {
      const raw = await readFile(abs, "utf8");
      const { body, meta } = parseFrontmatter(raw);
      const structuredData = structure(body);
      files.push({
        type: "page",
        path: rel,
        data: {
          title: meta.title,
          description: meta.description || meta.summary,
          structuredData,
        },
      });
      sections.push(
        ...pageSections(meta.title ?? rel, mcpUrl(rel), structuredData, linkListLabels(body)),
      );
      mcpPages.push({
        title: meta.title ?? rel,
        url: mcpUrl(rel),
        description: meta.description || meta.summary,
        text: plainText(body).slice(0, 1200),
      });
      pageCount++;
    } else if (abs.endsWith("meta.json")) {
      files.push({
        type: "meta",
        path: rel,
        data: JSON.parse(await readFile(abs, "utf8")),
      });
    }
  }

  const source = loader({ source: { files }, baseUrl: "/" });
  // Results use relevance and page-group ranking, never field-based sorting.
  // Do not ship a second copy of every document in unused sorting indexes.
  const server = createFromSource(source, { sort: { enabled: false } });
  const exported = await server.export();

  await mkdir(join(distDir, "api"), { recursive: true });
  await writeFile(join(distDir, "api", "search.json"), JSON.stringify(exported), "utf8");
  await writeFile(
    join(distDir, "api", "mcp-search.json"),
    JSON.stringify({ pages: mcpPages, release: await releaseInfo() }),
    "utf8",
  );
  // Section-level index behind GET /search.json (host/search.ts ranks it).
  await writeFile(join(distDir, "api", "sections.json"), JSON.stringify(sections), "utf8");
  console.log(
    `build-search: indexed ${pageCount} pages (${sections.length} sections) -> ` +
      "api/search.json + api/mcp-search.json + api/sections.json",
  );
}

const DOCS_ORIGIN = "https://docs.phux.sh";

/**
 * One record per heading (plus the untitled intro), in page order, from the
 * same structured data the Fumadocs index uses. Heading ids are the rendered
 * anchors, so `url` deep-links into the page.
 *
 * `linkShare` is the fraction of the section's paragraphs that are link-list
 * items (they open with one of `linkLabels`): a "More" or index section is
 * all pointers to other pages, and host/search.ts ranks it below the pages it
 * points at. Structured data has already dropped the link targets, so the
 * labels come from the raw Markdown (see linkListLabels).
 */
export function pageSections(page, route, structuredData, linkLabels = []) {
  // A heading that repeats the page title (a body `# Title`) is the page itself.
  const headings = structuredData.headings.filter((h) => inlineText(h.content) !== page);
  const titles = new Map(headings.map((h) => [h.id, h.content]));
  const byHeading = new Map();
  byHeading.set("", []);
  for (const { id } of headings) byHeading.set(id, []);
  for (const { heading, content } of structuredData.contents) {
    const key = heading && byHeading.has(heading) ? heading : "";
    byHeading.get(key).push(content);
  }
  const out = [];
  for (const [id, parts] of byHeading) {
    const text = inlineText(parts.join(" "));
    if (id === "" && text === "") continue;
    const anchor = id ? `#${id}` : "";
    out.push({
      url: `${DOCS_ORIGIN}${route}${anchor}`,
      markdown: `${DOCS_ORIGIN}${route}.md${anchor}`,
      page,
      heading: id ? inlineText(titles.get(id)) : page,
      text,
      linkShare: linkShare(parts, linkLabels),
    });
  }
  return out;
}

/** The labels of list items that open with a link (`- [Key bindings](/keys): …`). */
export function linkListLabels(markdown) {
  const items = markdown.matchAll(/^\s*(?:[-*+]|\d+\.)\s+\[([^\]]+)\]\(/gm);
  return [...new Set([...items].map((match) => inlineText(match[1])).filter(Boolean))];
}

/** Fraction of `parts` that open with a link-list label, to two decimals. */
function linkShare(parts, labels) {
  if (parts.length === 0 || labels.length === 0) return 0;
  const isLinkItem = (part) => {
    const text = inlineText(part);
    return labels.some((label) => text.startsWith(label));
  };
  const linked = parts.filter(isLinkItem).length;
  return Math.round((linked / parts.length) * 100) / 100;
}

/** Strip inline markdown from one structured-data paragraph. */
function inlineText(value) {
  return String(value ?? "")
    .replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/<\/?[a-z][^>]*>/gi, "")
    .replace(/[*`]+/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

/** Bare canonical route for a synced markdown path (matches trailingSlash "never"). */
function mcpUrl(rel) {
  const route = rel.replace(/\.md$/, "").replace(/(^|\/)index$/, "");
  return route === "" ? "/" : `/${route}`;
}

/** Crude markdown-to-plain-text for MCP keyword search. */
function plainText(body) {
  return body
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/[*_`>|-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

async function releaseInfo() {
  const raw = await readFile(join(ROOT, "src/lib/release.json"), "utf8").catch(() => null);
  const release = raw ? JSON.parse(raw) : {};
  return {
    phux: {
      tag: release.tag ?? "unknown",
      url: release.url ?? "https://github.com/no-phux/phux/releases",
      publishedAt: release.publishedAt ?? "unknown",
    },
    desktop: {
      tag: release.desktop?.tag ?? "unknown",
      url: release.desktop?.url ?? "https://github.com/no-phux/phux/releases",
      publishedAt: release.desktop?.publishedAt ?? "unknown",
    },
  };
}
